  set_pixel(9, 22, "#36042236");
  set_pixel(10, 22, "#3c04273c");
  fill_rect(11, 22, 2, 1, "#3e03283e");
  set_pixel(13, 22, "#3c04273c");
  set_pixel(14, 22, "#35032235");
  set_pixel(15, 22, "#2b031c2b");
  set_pixel(16, 22, "#1e02131e");
