// Centro del orbe y distancia de cada píxel al centro.
const CX = 11.5, CY = 11.5;
const dist = (x, y) => Math.hypot(x - CX, y - CY);

// Tonos del halo tomados de la base (magenta oscuro translúcido), de más tenue a más intenso.
const HALO = ["#01000101", "#04000304", "#09000609", "#0e00090e", "#13000c13", "#19001019",
  "#1e02131e", "#27031927", "#30031f30", "#37042437", "#3c04273c", "#53053653"];
const haloAlpha = (c) => parseInt(c.slice(7, 9), 16);

// Halo exterior (fuera del aro oscuro, d >= 10). escala: cuánto se abre; brillo: 0..1.
part("halo", ({ escala, brillo }) => {
  for (let y = -4; y < 28; y++) {
    for (let x = -4; x < 28; x++) {
      const d = dist(x, y);
      if (d < 10) continue;
      const a = 90 * brillo * Math.exp(-(((d - 10) / (1.4 * escala)) ** 2));
      if (a < 1) { set_pixel(x, y, "transparent"); continue; }
      let best = HALO[0];
      for (const c of HALO) if (Math.abs(haloAlpha(c) - a) < Math.abs(haloAlpha(best) - a)) best = c;
      set_pixel(x, y, best);
    }
  }
});

// Núcleo blanco: tam = 1 crece un píxel, tam = -1 encoge un píxel.
part("nucleo", ({ tam }) => {
  for (let y = 4; y < 20; y++) {
    for (let x = 4; x < 20; x++) {
      const d = dist(x, y);
      if (tam > 0) {
        if (d <= 4.2) set_pixel(x, y, "#ffffff");
        else if (d <= 5.2) set_pixel(x, y, "#fff6fd");
        else if (d <= 5.9) set_pixel(x, y, "#ffcaf1");
      } else if (tam < 0) {
        if (d > 2.6 && d <= 3.6) set_pixel(x, y, "#ffcaf1");
        else if (d > 3.6 && d <= 4.6) set_pixel(x, y, "#ff96e2");
        else if (d > 4.6 && d <= 5.4) set_pixel(x, y, "#ff69cf");
      }
    }
  }
});

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
// Se usa el sello base(): la receta difiere en 1 nivel de color en algunos píxeles translúcidos.
rest(() => {
  base();
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("pulso", { frames: 4, fps: 12, loop: true }, (f, { t }) => {
  base();
  const tam = cycle([0, 1, 0, -1], f);
  if (tam !== 0) draw("nucleo", { tam });
  if (f > 0) {
    const [escala, brillo] = cycle([[1, 1], [1.25, 1.05], [1.55, 0.6], [1.8, 0.3]], f);
    draw("halo", { escala, brillo });
  }
});

